-- ============================================================
-- Service Follow-ups (2026-11-04)
--
-- Every call / visit logged on a service enquiry (the call pop-up
-- of Service Enquiries : phone icon on the list, Add follow-up on
-- the form).
--
-- Plain statements only : run in a NEW pgAdmin Query Tool with
-- F5. Safe to run again.
-- ============================================================

CREATE TABLE IF NOT EXISTS public."ServiceFollowUps"
(
    "ServiceFollowUpId"      bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ServiceEnquiryId"       bigint                 NOT NULL,
    "EnquiryNo"            character varying(30)  NOT NULL DEFAULT '',
    "FollowUpAt"           timestamp with time zone NOT NULL DEFAULT now(),
    "FollowUpDate"         date                   NOT NULL,
    "MethodId"             bigint                 NULL,
    "MethodName"           character varying(100) NOT NULL DEFAULT '',
    "Outcome"              character varying(30)  NOT NULL,
    "Note"                 character varying(500) NOT NULL DEFAULT '',
    "NextFollowUpDate"     date                   NULL,
    "StatusFromId"         bigint                 NULL,
    "StatusFromName"       character varying(100) NOT NULL DEFAULT '',
    "StatusToId"           bigint                 NOT NULL,
    "StatusToName"         character varying(100) NOT NULL DEFAULT '',
    "StatusToStage"        character varying(10)  NOT NULL DEFAULT '',
    "PreferredDateFrom"    date                   NULL,
    "PreferredDateTo"      date                   NULL,
    "LostReasonId"         bigint                 NULL,
    "LostReasonName"       character varying(100) NOT NULL DEFAULT '',
    "ExecutiveUserId"      bigint                 NOT NULL,
    "ExecutiveName"        character varying(150) NOT NULL DEFAULT '',
    "IsDeleted"            boolean                NOT NULL DEFAULT false,
    "DeletedBy"            bigint                 NULL,
    "DeletedDate"          timestamp with time zone NULL,
    "CreatedBy"            bigint                 NOT NULL,
    "CreatedDate"          timestamp with time zone NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS "IX_ServiceFollowUps_Enquiry_At" ON public."ServiceFollowUps" ("ServiceEnquiryId", "FollowUpAt");

CREATE INDEX IF NOT EXISTS "IX_ServiceFollowUps_Date" ON public."ServiceFollowUps" ("FollowUpDate");
